-- One slot. Draft only.
BEGIN;
-- PT115-S2-Q14
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND q.stimulus=$batch01$Activist: Although the environmental bill before the legislature is popular with voters, it will have mainly negative economic consequences if it is passed, especially when we try to lure new businesses to our country. Great leaders have the courage to look beyond popularity to what is sound policy; legislators ought to do the same by not voting for this bill.$batch01$ AND q.prompt=$batch01$The activist's argumentation is most vulnerable to criticism on the grounds that it$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT115-S2-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S2-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$presumes, without providing justification, that most of the legislators are great leaders$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT115-S2-Q14 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$presumes, without providing justification, that a bill is less likely to pass if it is deemed to have negative economic consequences$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT115-S2-Q14 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$fails to consider whether there are noneconomic reasons for supporting the bill that outweigh the reason given for rejecting it$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT115-S2-Q14 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$fails to specify whether legislators usually consider economic consequences when a bill is before the legislature$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT115-S2-Q14 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$takes for granted that if a bill is popular, it will not be sound economically$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT115-S2-Q14 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT115-S2-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Legislators should vote against the environmental bill.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$It is popular but would have mainly negative economic consequences, especially for attracting new businesses. Great leaders look beyond popularity to sound policy.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The bill's economic costs matter, and popularity by itself would not justify it. But a vote requires weighing *all* important consequences. Environmental or health benefits might outweigh those costs. The speaker gives a reason against the bill and treats it as decisive without examining potential reasons for it.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the omitted noneconomic benefits that could outweigh the acknowledged economic downside.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Legislators need not be great leaders for the activist to urge them to follow the conduct attributed to great leaders.$batch01$), ($batch01$B$batch01$, $batch01$The conclusion recommends how legislators ought to vote, not a prediction of whether the bill is likely to pass.$batch01$), ($batch01$C$batch01$, $batch01$The economic drawback may be outweighed by noneconomic reasons to support the bill. Without comparing the costs with potential benefits, the activist cannot conclude that sound policy requires voting no.$batch01$), ($batch01$D$batch01$, $batch01$Whether legislators *usually* consider economics does not determine how they ought to vote on this bill. The gap lies in the omitted reasons for passing it.$batch01$), ($batch01$E$batch01$, $batch01$The activist explicitly grants that the bill is popular while arguing that it is economically harmful. He does not infer harm from popularity.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
